def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(min(budget, 18.0))

    pressure = 0.0
    max_prev_bid = 0.0
    urgent_opp = 0
    active_opp = 0
    for opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        pbid = prev.get('bid')
        if pbid is not None:
            try:
                pbid = float(pbid)
            except:
                pbid = 0.0
            if pbid > max_prev_bid:
                max_prev_bid = pbid
            pressure += pbid
            if pbid > 0:
                active_opp += 1
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1

    avg_pressure = pressure / max(1, len(alive))

    # Since supply < 2 * WATER_REQ in this scenario, at most one full allocation is feasible.
    # Use conservative bids unless survival risk is high.
    if hp <= 2 or no_water >= 2:
        bid = min(budget, max(62.0, max_prev_bid + 2.0))
        return float(max(0.0, bid))

    if hp <= 4 or no_water >= 1:
        bid = min(budget, max(45.0, min(68.0, max_prev_bid + 1.0)))
        return float(max(0.0, bid))

    if max_prev_bid >= 120.0:
        bid = 16.0
    elif max_prev_bid >= 80.0:
        bid = 18.0
    elif max_prev_bid >= 40.0:
        bid = 24.0
    elif active_opp == 0:
        bid = 14.0
    else:
        bid = max(20.0, avg_pressure * 0.75 + 2.0)

    if urgent_opp >= 2:
        bid -= 4.0
    elif urgent_opp == 0 and day >= 7 and hp >= 7:
        bid += 3.0

    reserve = DAILY_SALARY * max(0, 10 - day)
    if budget > reserve + 120:
        bid += 4.0

    bid = min(budget, max(0.0, bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(float(my_status['budget']), DAILY_SALARY * 0.4))

    # Read yesterday bids to infer pressure level.
    yesterday_bids = []
    yesterday_info = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b_val = float(b)
            except Exception:
                continue
            yesterday_bids.append(b_val)
            yesterday_info.append((oid, b_val, prev.get('hp_after', None), prev.get('status', None)))

    # If no trace bids, fall back to conservative mid bidding.
    if not yesterday_bids:
        base = 0.55 * DAILY_SALARY
        if float(my_status['hp']) <= 2:
            base = 0.85 * DAILY_SALARY
        return max(0.0, min(float(my_status['budget']), base))

    highest_prev_bid = max(yesterday_bids)

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    no_water_days = int(my_status.get('no_water_days', 0))

    # Pressure mapping: if someone bid near or above Cindy-like level, we must contest.
    # Cindy's max/avg were ~142.5; use that as a proxy threshold.
    contest_threshold = 0.80 * DAILY_SALARY  # 72
    strong_threshold = 1.20 * DAILY_SALARY   # 108

    # Supply factor: with medium supply in [15,25], water is scarce; bid slightly more.
    # Map supply to a multiplier in [0.95, 1.15]
    if MAX_SUPPLY == MIN_SUPPLY:
        supply_mult = 1.0
    else:
        supply_mult = 0.95 + 0.20 * ((supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY))

    # Base bid depends on my HP and how many dry days already.
    if my_hp <= 2 or no_water_days >= 2:
        base = 0.88 * DAILY_SALARY
    elif my_hp <= 4:
        base = 0.70 * DAILY_SALARY
    else:
        base = 0.58 * DAILY_SALARY

    # Decide escalation vs. underbidding.
    if highest_prev_bid >= strong_threshold:
        # Someone was willing to pay a lot; match/beat slightly if we can.
        bid = max(base, (highest_prev_bid * 1.02))
    elif highest_prev_bid >= contest_threshold:
        # Moderate contest: try to be competitive but not wasteful.
        bid = max(base, (highest_prev_bid * 0.90 + 6.0))
    else:
        # Low bids elsewhere: we can shade downward.
        bid = base * 0.95

    bid *= supply_mult

    # Ensure we can afford it.
    bid = max(0.0, min(my_budget, bid))

    # If we are extremely low budget, still bid something minimal to avoid full dry streak.
    if my_budget <= 5.0:
        return max(0.0, my_budget)

    # Small epsilon to break ties.
    return float(bid + 0.01)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 10.0)

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    max_prev = max(prev_bids) if prev_bids else 0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    if supply < 18:
        return min(my_status['budget'], max(max_prev * 1.05, DAILY_SALARY * 0.6))

    return min(my_status['budget'], max(max_prev * 0.9, DAILY_SALARY * 0.4))
